def run_length_encode(s: str) -> str:
    """'aaabbc' -> 'a3b2c1'"""
    if not s:
        return ''
    out = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            out.append(f'{s[i - 1]}{count}')
            count = 1
    out.append(f'{s[-1]}{count}')
    return ''.join(out)


def run_length_decode(s: str) -> str:
    """'a3b2c1' -> 'aaabbc'"""
    import re
    return ''.join(ch * int(n) for ch, n in re.findall(r'(\w)(\d+)', s))

# Examples:
print(run_length_encode('aaabbc'))   # a3b2c1
print(run_length_decode('a3b2c1'))   # aaabbc

