function runLengthEncode(s) {
    let out = '';
    let count = 1;
    for (let i = 1; i <= s.length; i++) {
        if (s[i] === s[i - 1]) {
            count++;
        } else {
            out += s[i - 1] + count;
            count = 1;
        }
    }
    return out;
}

function runLengthDecode(s) {
    return s.replace(/(\w)(\d+)/g, (_, ch, n) => ch.repeat(Number(n)));
}

