#include <string>
#include <sstream>
#include <vector>
#include <algorithm>

std::string reverseWords(const std::string& sentence) {
    std::istringstream in(sentence);
    std::vector<std::string> words;
    std::string w;
    while (in >> w) words.push_back(w);
    std::reverse(words.begin(), words.end());
    std::string out;
    for (size_t i = 0; i < words.size(); i++) {
        if (i) out += " ";
        out += words[i];
    }
    return out;
}

